module TweakDock
  class Generator
    STRING_ESCAPES = { "\\" => "\\\\", "\"" => "\\\"", "\n" => "\\n", "\r" => "\\r", "\t" => "\\t" }.freeze

    def initialize(spec)
      @spec = spec
    end

    def swift
      <<~SWIFT
        // Generated by tweakdock from #{File.basename(@spec.path)}. Do not edit.

        import TweakDock

        #{@spec.store ? "@Tweaks(store: #{@spec.store})" : '@Tweaks'}
        #{access}enum #{@spec.type_name} {
        #{@spec.experiments.map { |experiment| indent(member(experiment)) }.join("\n\n")}
        }
      SWIFT
    end

    private

    def member(experiment)
      type = experiment.type_name
      arguments = [
        "collection: #{string(@spec.collection)}",
        "group: #{string(experiment.group)}",
        "name: #{string(experiment.key)}",
        "defaultValue: #{type}.#{Naming.escaped(experiment.default)}",
        "from: #{source(experiment)}"
      ]
      <<~SWIFT.chomp
        #{access}enum #{type}: String, CaseIterable, TweakValue {
            case #{experiment.variants.map { |variant| Naming.escaped(variant) }.join(', ')}
        }

        @Tweak(
        #{indent(arguments.join(",\n"))}
        )
        #{access}static var #{Naming.escaped(experiment.property_name)}: #{type}
      SWIFT
    end

    def source(experiment)
      return ".experiment(#{string(experiment.key)})" if experiment.all_devices?

      devices = experiment.devices.map { |device| ".#{device}" }
      list = devices.one? ? devices.first : "[#{devices.join(', ')}]"
      ".experiment(#{string(experiment.key)}, devices: #{list})"
    end

    def access
      @spec.access ? "#{@spec.access} " : ""
    end

    def string(text)
      escaped = text.gsub(/[\\"[:cntrl:]]/) { |character| STRING_ESCAPES[character] || format("\\u{%X}", character.ord) }
      "\"#{escaped}\""
    end

    def indent(text)
      text.lines.map { |line| line.strip.empty? ? line : "    #{line}" }.join
    end
  end
end
